sys_script.script:
(function executeRule(current, previous) {

    /* ======================================================
       CAMPUSMATCH
       INVALIDATE COLLECTION QR AFTER CLAIM WITHDRAWAL
    ====================================================== */


    /* ======================================================
       SAFETY
    ====================================================== */

    if (
        !current ||
        !current.isValidRecord()
    ) {

        return;

    }


    /* ======================================================
       FIND CLAIM STATUS FIELD
    ====================================================== */

    var statusField = '';


    if (
        current.isValidField(
            'claim_status'
        )
    ) {

        statusField =
            'claim_status';

    }
    else if (
        current.isValidField(
            'u_claim_status'
        )
    ) {

        statusField =
            'u_claim_status';

    }


    if (
        !statusField
    ) {

        gs.error(
            'CampusMatch Withdrawal: Claim Status field not found.'
        );

        return;

    }


    /* ======================================================
       RUN ONLY WHEN STATUS CHANGES TO WITHDRAWN
    ====================================================== */

    if (
        !current[
            statusField
        ].changesTo(
            'withdrawn'
        )
    ) {

        return;

    }


    try {

        /* ==================================================
           FIND COLLECTION TOKEN FIELD

           Your instance has used collection_toke0 earlier,
           but this also supports collection_token if the
           field was later corrected.
        ================================================== */

        var tokenField =
            '';


        if (
            current.isValidField(
                'collection_toke0'
            )
        ) {

            tokenField =
                'collection_toke0';

        }
        else if (
            current.isValidField(
                'collection_token'
            )
        ) {

            tokenField =
                'collection_token';

        }


        /* ==================================================
           INVALIDATE TOKEN
        ================================================== */

        if (
            tokenField
        ) {

            var claim =
                new GlideRecord(
                    current.getTableName()
                );


            if (
                claim.get(
                    current.getUniqueValue()
                )
            ) {

                claim.setWorkflow(
                    false
                );


                claim.setValue(
                    tokenField,
                    ''
                );


                claim.update();


                gs.info(
                    'CampusMatch: Collection token invalidated for withdrawn Claim ' +
                    current.getDisplayValue(
                        'number'
                    )
                );

            }

        }
        else {

            gs.warn(
                'CampusMatch Withdrawal: No Collection Token field found for Claim ' +
                current.getUniqueValue()
            );

        }

    }
    catch (ex) {

        gs.error(
            'CampusMatch Withdrawal: Failed to invalidate collection token. Error: ' +
            ex.message
        );

    }


})(current, previous);
